class Solution {
public:
    string encode(int num) {
        long long value = static_cast<long long>(num) + 1;
        string result;
        while (value > 1) {
            result.push_back(char('0' + (value & 1)));
            value >>= 1;
        }
        reverse(result.begin(), result.end());
        return result;
    }
};
